import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`main`,heroTitle:`Put Perplexity Computer to work on any task`,heroSubtitle:`Perplexity Computer researches, plans, writes, analyzes, and executes multi-step workflows across your tools — automatically.`,hasInputUrl:!1,hasPromptInput:!0,heroOverlaySteps:[`Breaking your goal into specialized tasks and workflows`,`Choosing the best AI model and tool for each step`,`Coordinating research, analysis, and execution across apps`,`Finished deliverables assembled — ready to review`],generatingSteps:[`Breaking your request into the right sequence of specialized tasks`,`Designing an agent workflow that routes each step to the best-fit model`,`Configuring research, analysis, writing, and execution across your tools`,`Setting up a complete workflow so the final deliverable is ready to use`],featureSectionTitle:`From one prompt to complete workflows`,featureCardTitles:[`Connects to your entire stack`,`Outputs you can use immediately`],featureCardDescriptions:[`Computer decomposes your work into subtasks, spins up specialized agents, and assigns each one to the AI model that performs best.`,`Google Drive, Sheets, Notion, Slack, GitHub, Airtable, and more — Computer can pull context from your tools and push the finished work back where it belongs.`,`Research briefs. Spreadsheets. Slides. Outreach drafts. Operating plans. Complete deliverables — not isolated answers from a single model.`],capabilitySectionTitle:`Your AI team, on autopilot`,capabilitySectionSubtitle:`Give Computer a goal, step away, and come back to finished work.`,capabilityCards:[{title:`Research & Analysis`,description:`Computer can search the live web, gather current data, compare sources, and synthesize the findings into a structured point of view.`},{title:`Writing & Synthesis`,description:`Computer can turn raw inputs into polished drafts, reports, summaries, and presentations tailored to the task at hand.`},{title:`Workflow Automation`,description:`Computer can chain together multi-step tasks, carry context from one step to the next, and keep long-running work moving without supervision.`},{title:`Connect Your Tools`,description:`Computer can work across the apps your team already uses so data gathering, execution, and handoff all happen in one workflow.`},{title:`Remember & Learn`,description:`Computer can remember your preferences, prior outputs, and working context so repeated tasks get sharper over time.`},{title:`Monitor & Alert`,description:`Computer can keep watching for changes in data, projects, or external signals and surface what needs your attention next.`}]});export{t as default};
